IF DB_NAME() NOT LIKE N'ClubStage7Test[_]%' THROW 51000, N'Используйте отдельную тестовую базу ClubStage7Test_...', 1;
SET NOCOUNT ON;
DECLARE @r table(n int,title nvarchar(100),passed bit);
INSERT @r SELECT 1,N'10 таблиц',IIF((SELECT COUNT(*) FROM sys.tables)=10,1,0);
INSERT @r SELECT 2,N'9 внешних ключей',IIF((SELECT COUNT(*) FROM sys.foreign_keys)=9,1,0);
INSERT @r SELECT 3,N'total_cost исключён из sessions',IIF(COL_LENGTH('dbo.sessions','total_cost') IS NULL,1,0);
EXEC dbo.start_session 1,1,1;
DECLARE @s int=(SELECT MAX(session_id) FROM dbo.sessions);
INSERT @r SELECT 4,N'Открытие сеанса',IIF(EXISTS(SELECT 1 FROM dbo.sessions WHERE session_id=@s AND end_time IS NULL),1,0);
BEGIN TRY EXEC dbo.start_session 2,1,1; INSERT @r VALUES(5,N'Занятый ПК',0); END TRY BEGIN CATCH INSERT @r VALUES(5,N'Занятый ПК',IIF(ERROR_NUMBER() IN(2601,2627),1,0)); END CATCH;
BEGIN TRY EXEC dbo.start_session 1,2,1; INSERT @r VALUES(6,N'Повторный активный клиент',0); END TRY BEGIN CATCH INSERT @r VALUES(6,N'Повторный активный клиент',IIF(ERROR_NUMBER() IN(2601,2627),1,0)); END CATCH;
BEGIN TRY EXEC dbo.start_session 2,3,1; INSERT @r VALUES(7,N'ПК на обслуживании',0); END TRY BEGIN CATCH INSERT @r VALUES(7,N'ПК на обслуживании',IIF(ERROR_NUMBER()=50002,1,0)); END CATCH;
BEGIN TRY EXEC dbo.pay_session @s,1; INSERT @r VALUES(8,N'Оплата активного запрещена',0); END TRY BEGIN CATCH INSERT @r VALUES(8,N'Оплата активного запрещена',IIF(ERROR_NUMBER()=50005,1,0)); END CATCH;
EXEC dbo.finish_session @s;
INSERT @r SELECT 9,N'Завершение',IIF(EXISTS(SELECT 1 FROM dbo.sessions WHERE session_id=@s AND end_time IS NOT NULL AND session_status_id=2),1,0);
BEGIN TRY EXEC dbo.finish_session @s; INSERT @r VALUES(10,N'Повторное завершение',0); END TRY BEGIN CATCH INSERT @r VALUES(10,N'Повторное завершение',IIF(ERROR_NUMBER()=50004,1,0)); END CATCH;
EXEC dbo.pay_session @s,1;
INSERT @r SELECT 11,N'Оплата и is_paid',IIF(EXISTS(SELECT 1 FROM dbo.v_session_costs WHERE session_id=@s AND is_paid=1),1,0);
BEGIN TRY EXEC dbo.pay_session @s,1; INSERT @r VALUES(12,N'Повторная оплата',0); END TRY BEGIN CATCH INSERT @r VALUES(12,N'Повторная оплата',IIF(ERROR_NUMBER() IN(2601,2627),1,0)); END CATCH;
BEGIN TRY UPDATE dbo.tariffs SET price_per_hour=121 WHERE tariff_id=1; INSERT @r VALUES(13,N'Защита цены тарифа',0); END TRY BEGIN CATCH INSERT @r VALUES(13,N'Защита цены тарифа',IIF(ERROR_NUMBER()=50001,1,0)); END CATCH;
DECLARE @start datetime2(0)='2026-01-01T12:00:00';
INSERT dbo.sessions(client_id,computer_id,tariff_id,start_time,end_time,session_status_id) VALUES(1,1,1,@start,@start,2),(1,1,1,@start,DATEADD(second,60,@start),2),(1,1,1,@start,DATEADD(second,61,@start),2),(1,1,1,@start,DATEADD(second,3600,@start),2);
INSERT @r SELECT 14,N'0 секунд = 0 рублей',IIF(EXISTS(SELECT 1 FROM dbo.v_session_costs WHERE start_time=@start AND end_time=@start AND total_cost=0),1,0);
INSERT @r SELECT 15,N'60 секунд = 2 рубля',IIF(EXISTS(SELECT 1 FROM dbo.v_session_costs WHERE start_time=@start AND end_time=DATEADD(second,60,@start) AND total_cost=2),1,0);
INSERT @r SELECT 16,N'61 секунда = 4 рубля',IIF(EXISTS(SELECT 1 FROM dbo.v_session_costs WHERE start_time=@start AND end_time=DATEADD(second,61,@start) AND total_cost=4),1,0);
INSERT @r SELECT 17,N'3600 секунд = 120 рублей',IIF(EXISTS(SELECT 1 FROM dbo.v_session_costs WHERE start_time=@start AND end_time=DATEADD(second,3600,@start) AND total_cost=120),1,0);
BEGIN TRY INSERT dbo.sessions(client_id,computer_id,tariff_id,start_time,end_time,session_status_id) VALUES(1,1,1,@start,DATEADD(second,-1,@start),2); INSERT @r VALUES(18,N'Отрицательная длительность',0); END TRY BEGIN CATCH INSERT @r VALUES(18,N'Отрицательная длительность',IIF(ERROR_NUMBER()=547,1,0)); END CATCH;
SELECT * FROM @r ORDER BY n;
SELECT SUM(CAST(passed AS int)) AS passed,COUNT(*) AS total FROM @r;
IF EXISTS (SELECT 1 FROM @r WHERE passed=0) THROW 51001, N'Есть ошибки проверки', 1;
